import{_ as s,o as t,c as o,a0 as i}from"./chunks/framework.BywSET8q.js";const p=JSON.parse('{"title":"Sessions","description":"","frontmatter":{"next":{"text":"Managing User Credentials","link":"/docs/guides/Credential"}},"headers":[],"relativePath":"docs/concepts/sessions.md","filePath":"docs/concepts/sessions.md"}'),a={name:"docs/concepts/sessions.md"};function n(r,e,c,d,h,l){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h1><p>Traditional cookie-based sessions and OAuth2 token-based sessions differ fundamentally in how they manage user authentication and state. It&#39;s important to understand these differences and how they may affect your application and overall architecture. While cookie-based sessions are common in traditional web applications, OAuth2 token-based sessions are preferred for APIs and mobile apps due to their statelessness, scalability, and flexible security features.</p><h2 id="cookie-based-sessions" tabindex="-1">Cookie-based Sessions <a class="header-anchor" href="#cookie-based-sessions" aria-label="Permalink to &quot;Cookie-based Sessions&quot;">​</a></h2><p>In a cookie-based session, after a user successfully authenticates, the server creates a session and stores user information on the server side. The client receives a session ID, which is stored as a cookie and sent with every subsequent request, allowing the server to identify the user and retrieve their session data. Sessions commonly have an expiration time (usually 24 hours or less); the session is considered terminated when either:</p><ol><li>The cookie is deleted from the browser, or</li><li>The user&#39;s information is removed from the server-side session store.</li></ol><h2 id="oauth2-token-based-sessions" tabindex="-1">OAuth2 Token-based Sessions <a class="header-anchor" href="#oauth2-token-based-sessions" aria-label="Permalink to &quot;OAuth2 Token-based Sessions&quot;">​</a></h2><p>In contrast, with OAuth2 token-based authentication, after a user successfully authenticates, the <code>Authorization Server</code> issues two types of tokens: access tokens and refresh tokens. The access token is a short-lived credential (often a JSON Web Token, or <code>JWT</code>) that grants the client permission to access protected resources or APIs on behalf of the user. This token is typically included in the <code>Authorization</code> header of each request to the server, and it contains encoded information such as user identity, scopes (permissions), and an expiration timestamp. Because access tokens are short-lived, they minimize security risks if intercepted.</p><p>However, to avoid forcing users to re-authenticate frequently when an access token expires, OAuth2 introduces the refresh token. The refresh token is a long-lived credential issued alongside the access token, but unlike the access token, it is only sent to the authentication server and never exposed to resource servers or APIs. When the access token expires, the client can use the refresh token to request a new access token without needing the user to log in again. This process allows for seamless, uninterrupted user sessions while maintaining security, as refresh tokens can be revoked or rotated if compromise is suspected. In summary, access tokens are used for accessing resources and expire quickly for security, while refresh tokens are used to obtain new access tokens and support long-lived, stateless sessions in OAuth2 systems.</p><p>This is an important distinction. The access token represents the user&#39;s proof of authentication (similar to a session cookie), however the refresh token represents the activeness of the user&#39;s session (similar to a server-side session store). A session can be considered active until the refresh token expires, since access tokens can be easily replaced without prompting the user.</p><h3 id="terminating-token-based-sessions" tabindex="-1">Terminating Token-based Sessions <a class="header-anchor" href="#terminating-token-based-sessions" aria-label="Permalink to &quot;Terminating Token-based Sessions&quot;">​</a></h3><p>Resource servers have a few options to validate access tokens from incoming requests.</p><ol><li>Access tokens issued by Okta Custom Authorization Servers are <code>JWTs</code>. The signature of the <code>JWT</code> can be verified, ensuring the token&#39;s validity. Once the <code>JWT</code> is determined to have a valid signature, the expiration date should be checked as well. <ul><li>This approach is decentralized, meaning the resource server can verify the <code>JWT</code> itself (with access to the corresponding public key).</li><li>This approach <strong>DOES NOT</strong> handle revoked tokens. An unexpired but revoked token will still pass this verification.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>This approach only works with Okta <a href="https://developer.okta.com/docs/concepts/auth-servers/#custom-authorization-server" target="_blank" rel="noreferrer">Custom Authorization Servers</a></p></div></li><li>An <code>OAuth2</code> <a href="https://developer.okta.com/docs/api/openapi/okta-oauth/oauth/tag/OrgAS/#tag/OrgAS/operation/introspect" target="_blank" rel="noreferrer"><code>introspect</code></a> request can be made to obtain the validity of a token. A <code>JSON</code> payload with the token&#39;s claims will be returned. In addition, the <code>active</code> (<code>boolean</code>) property will indicate if the token is still active (not revoked or expired). <ul><li>While this approach handles revoked tokens, it&#39;s significantly more expensive since it requires a network request per access token.</li></ul></li></ol>',12)])])}const k=s(a,[["render",n]]);export{p as __pageData,k as default};
